from importlib.machinery import SourceFileLoader
from pathlib import Path
p=Path(__file__).parent;m=SourceFileLoader('tle',str(p/'author-helper.py')).load_module()
ACT='Gabay na 30 minuto: 10 pag-unawa sa teksto, 8 pag-aayos ng halimbawa, 9 pagsulat, 3 pagbalik-tanaw.\n'
m.lesson(65,'Solder, flux, at rework','Pagsamahin ang materyal, ibabaw, init, paghawak, at inspeksiyon.',[
('Alloy at kondisyon','Magkaiba ang composition, melting point, wetting ng leaded at lead-free solder. Halimbawa, hindi laging pareho ang kondisyon ng Sn63/Pb37 at Sn-Ag-Cu sa materyal. Huwag sabihing lahat ng lead-free ay mababa ang kalidad; gamitin ang qualified material at process conditions.'),('Paghahanda ng ibabaw','Tumutulong ang flux sa oxide treatment at wetting. Pagsamahin ang cleaning, tamang init, holding, supply, cooling, inspection. Iba ang residue cleaning requirement at solvent sa flux/specification; huwag parehong panlinis sa lahat.'),('Pagwawasto nang hindi dumadagdag ang depekto','Iangkop ang tip shape/condition at iwasan ang land peeling mula matagal na init o force. Kilalanin ang bridge, crack, at solder shortage at gumamit ng aprubadong rework/reinspection. Huwag shine lamang ang pass/fail.')],['Materyal na tumutulong sa oxide treatment at wetting sa soldering.','Bagay na natitira matapos ang proseso.','Conductor area sa board para sa component terminal at iba pa.','Bitak sa materyal o joint.'],ACT+'Gumawa ng checklist ng material label, conditions, residue, inspection, at rework approval. Sumulat ng ulat ng hinalang halo-halong alloys.',['Tingnan ang product info/procedure sa lead, cleaners, ventilation, at burn prevention.'],'Pagsamahin ang materyal, ibabaw, init, paghawak, at inspeksiyon.')
m.lesson(66,'Passive components at temperature/vibration elements','Itugma ang structure, properties, rating, at gamit bukod sa value.',[
('Mga uri ng resistor','Iba ang structure/gamit ng carbon film, metal, wirewound, chip, variable, at trimmer. Kahit parehong value, tingnan ang power, temperature coefficient, size, frequency response. Tingnan din ang variable pinout at adjustment range.'),('Ano ang iniimbak','Passive capacitor ang nag-iimbak ng energy sa electric field at coil sa magnetic field. Basahin ang capacitance, inductance, allowable current. Hindi ibig sabihing ligtas hawakan ang passive; kailangan ang residual-charge/heat precautions.'),('Mga espesyal na katangian','Thermistor:resistance ayon sa temperature;piezo:force-electricity relation;crystal:stable vibration. Ihiwalay sa receiver/emitter at huwag basta ipalit ang kamukha.')],['Components na kumokonsumo,nag-iimbak,o naglalabas ng external energy.','Elementong gumagamit ng temperature-dependent resistance.','Elementong gumagamit ng force/electricity relation.','Piyesang gumagamit ng vibration ng crystal.'],ACT+'Ibuod ang resistor,capacitor,coil,thermistor,crystal roles/specs. Magbigay ng dalawang panganib kahit passive.',['Huwag laktawan ang power isolation at residual-energy check kahit passive.'],'Itugma ang structure, properties, rating, at gamit bukod sa value.')
m.lesson(67,'Pagkilala sa lathe,milling,at NC machines','Ihiwalay ang machine ayon sa umiikot at layunin.',[
('Alin ang umiikot','Sa lathe,umiikot ang workpiece at pinuputol ang outside,inside,groove,thread. Sa milling,tool ang umiikot at relative movement sa fixed workpiece ang gumagawa ng plane,side,step,groove. Huwag isang machine lamang mula hugis ng produkto.'),('Drilling at grinding','Drill press ang fixed workpiece na pinuputol ng drill/reamer;grinder ang paunti-unting cutting gamit ang wheel. Iba ang edge at machine ng drill,lathe tool,end mill;huwag ipalit ang kamukha.'),('Numerical control at automatic change','NC ang pangkalahatang numerical control,kasama ang NC lathe/mill/machining center. May automatic tool change ang machining center. Kahit may program,kailangan ang origin,tool,jig,interference checks;hindi walang-kondisyong ligtas kahit unmanned.')],['Cutting tool sa lathe at iba pa.','Numerical control.','NC machine na may automatic tool change.','Hindi nilalayong contact ng tool o parts.'],ACT+'Piliin ang machine at umiikot na bagay para sa shaft diameter,flat groove,many holes,grinding finish. Isulat ang check bago unang machining.',['Huwag hawakan ang chuck,wheel,rotating tool;sundin ang stop,isolation,at assigned procedure.'],'Ihiwalay ang machine ayon sa umiikot at layunin.')
m.lesson(68,'Pagkalkula ng resistor dimensions,power,energy','Itugma ang material,dimensions,at constant conditions at ihiwalay ang W/Wh.',[
('Haba at area ng wire','Sa parehong materyal/temperature,R=ρℓ/S;mas mahaba mas resistive,mas area mas mababa. KungρayΩ·m at haba m,area ay m². Huwag diameter ang area at itala ang material/temperature.'),('Rate at total consumption','Sa DC resistor,P=VI=I²R=V²/Rpara sa W. Energy ay power×time sa Wh. Sa12V,60Ω,I=0.2A,P=2.4W. Sa30minuto,1.2Wh;magkaiba ang W at Wh.'),('Calculation at selection','Sa fixed voltage,mas maliit na R mas malaking power;sa fixed current,mas malaking R mas power. Linawin kung alin ang constant. Huwag computed power lamang;tingnan ang rating,cooling,temperature,protection.')],['Daming nagpapahayag ng resistivity ng materyal.','Lawak ng cross section.','Energy bawat unit time.','Kabuuang electrical energy sa takdang oras.'],ACT+'Hanapin ang resistance ratio kung2beses ang haba at3beses ang area ng parehong wire. Isulat sa units ang current,power,15minutong energy sa24V,120Ω.',['Huwag calculation ang dahilan sa unauthorized connection o rating excess.'],'Itugma ang material,dimensions,at constant conditions at ihiwalay ang W/Wh.')
m.lesson(69,'AC period/phase at DC transient state','Basahin ang frequency bilang cycles at ihiwalay ang ideal steady at tunay na transient.',[
('Isang cycle ang isang buong ulit','Frequency ng sine ay cycles bawat segundo,hindi basta direction reversals. Sa50Hz,20msang period;sa60Hz,humigit-kumulang16.7ms. Suriin ang nameplate frequency,hindi lugar lamang.'),('Time difference ng voltage/current','Sa ideal resistor-only sine circuit,in-phase;sa ideal coil,lagging ang current;sa ideal capacitor,leading. Ihambing ang parehong phase point;huwag ipaghalo ang height difference at time shift. May losses/multiple components sa real circuit.'),('May transition din sa DC','Huwag ilapat ang ideal DC steady coil/capacitor sa switching instant. Ginagamit ang mga ito sa real DC circuits. Isaalang-alang ang capacitor charging/residual charge at coil voltage sa current change;huwag basta i-short.')],['Posisyon sa periodic change.','Pareho ang timing ng corresponding periodic changes.','State habang lumilipat sa steady matapos condition change.','State na humupa ang pagbabago.'],ACT+'Kunin sa ms ang period ng25Hz. Ipaliwanag ang voltage/current ng ideal R,L,C at bakit hindi safety basis ang DCsteady lamang.',['Huwag mag-on/off o mag-short ng energy-storage parts sa tunay na makina bilang eksperimento.'],'Basahin ang frequency bilang cycles at ihiwalay ang ideal steady at tunay na transient.')
m.lesson(70,'Kirchhoff at pag-check ng series/parallel','Itakda ang arrows/polarity at check ang balance matapos equivalent calculation.',[
('Balance sa node','Current law:sum papasok=sum palabas. Halimbawa,8mAin at3mAsa isang branch,kaya5mAang natira. Itugma ang assumed arrows;negative answer ay opposite direction.'),('Potential differences sa loop','Voltage law:signed potential differences sa closed loop ay zero. Sa12Vrise at4V,8Vdrops,12−4−8=0. Huwag lahat positive nang walang kondisyon;itakda ang travel direction at polarity.'),('Combine bawat bahagi','Series:same current;parallel:same terminal voltage.120Ωparallel240Ω=80Ω;series sa40Ω=120Ω. Kunin ang total current,partial voltages,branch currents at check sa parehong laws.')],['Puntong pinagtatagpuan ng circuit branches.','Landas na bumabalik sa simula.','Law ng current balance sa node.','Law na zero ang signed potential sum sa loop.'],ACT+'Sa ideal18Vna40Ωseries sa(120Ωparallel240Ω),kalkulahin at check ang total current,parallel voltage,at dalawang branch current.',['Huwag gawing real wiring instruction ang ideal circuit.'],'Itakda ang arrows/polarity at check ang balance matapos equivalent calculation.')
m.lesson(71,'Intrinsic,n-type,p-type,at pn junction','Ihiwalay ang impurity,carrier,at internal field sa pn junction.',[
('Bonding at impurity','Mga intrinsic examples ang silicon/germanium. Sa angkop na maliit na impurity,nababago ang carriers. Electrons ang majority sa n-type,holes sa p-type;huwag ituring na simpleng negative/positive charge ng buong materyal ang n/p.'),('Donor at acceptor','Sa silicon,5-valence phosphorus ay donor example;3-valence boron ay acceptor. Hole ang kakulangan ng electron;sa galaw ng katabing electrons,itinuturing na gumagalaw ang hole.'),('Junction condition','Sa p/n junction,diffusion at recombination malapit sa boundary ang gumagawa ng depletion layer na kaunti ang movable majority carriers at internal field. Hindi walang-materyal na puwang o ganap na walang fixed charge. Nagbabago ang action ayon sa external voltage direction.')],['Outer electrons na kaugnay ng bonding.','Electrons o holes na nagdadala ng current.','Junction region na kaunti ang movable majority carriers.','Pagsasama ng electron/hole na nawawala bilang carriers.'],ACT+'Ihambing ang intrinsic,n,p sa carriers/impurities. Ipaliwanag sa diagram words ang hole motion at depletion layer.',['Huwag magpakuryente sa hindi alam na polarity/rating mula semiconductor explanation lamang.'],'Ihiwalay ang impurity,carrier,at internal field sa pn junction.')
m.lesson(72,'FET,IGBT,at IC functions','Ihiwalay ang control,characteristics,limits ng element at IC functions.',[
('Hindi pareho kahit tatlong terminal','Kumpara sa BJT B/C/E,FET ay field control sa gate. IGBT ay insulated-gate power device. Tingnan ang terminal names,drive,maximum ratings,static tolerance sa model data;hindi compatible dahil kamukha.'),('Characteristics at ratings','hFE,switching time,saturation voltage ay condition-dependent characteristics. Maximum current,voltage,loss ratings ay hindi lalampasang limits. Hindi isang magandang value lamang ang suitability.'),('Signal at processing','Iba ang op-amp,A/D,D/A,regulator,logic,memory,MPU. Modulation ang paglalagay ng signal sa carrier amplitude/frequency/phase;demodulation ang pagkuha. Huwag iisang processing ang amplification,oscillation,power stabilization.')],['Transistor na gumagamit ng field effect sa current control.','Bipolar power element na may insulated gate.','Voltage characteristic na natitira sa terminals sa takdang on conditions.','Microprocessor para sa arithmetic/control at iba pa.'],ACT+'Gumawa ng roles mula sensor sa MPU. Ipaliwanag ang checks sa FETgate/BJTbase at pagkakaiba ng characteristics/maximum ratings.',['Huwag ipalit ang ibang type mula terminal count lamang.'],'Ihiwalay ang control,characteristics,limits ng element at IC functions.')
